def solve(a, target):
    for i, value in enumerate(a):
        if value == target:
            return i
    return -1

def solve(a, target):
    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

